result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/syncdir.py", "content": "#!/usr/bin/env python3
"""One-way directory sync: SRC -> DST.

Usage:
    syncdir.py SRC DST [--delete] [--dry-run]

Actions (printed sorted, one per line, in --dry-run mode):
    COPY <relpath>    file exists in SRC but not in DST
    UPDATE <relpath>  file exists in both but size or sha256 differs
    DELETE <relpath>  file exists only in DST (only with --delete)
"""

import argparse
import hashlib
import os
import shutil
import sys


def sha256_of(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 16), b""):
            h.update(chunk)
    return h.hexdigest()


def walk_files(root):
    """Yield paths of all regular files under root as POSIX-style relative paths."""
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames.sort()
        for name in sorted(filenames):
            full = os.path.join(dirpath, name)
            if os.path.isfile(full) and not os.path.islink(full):
                yield os.path.relpath(full, root)


def plan(src_root, dst_root, delete=False):
    """Return the sorted list of (verb, relpath) actions for the sync."""
    src = {p: os.path.join(src_root, p) for p in walk_files(src_root)}
    dst = {p: os.path.join(dst_root, p) for p in walk_files(dst_root)}

    actions = []
    for rel, src_path in src.items():
        if rel not in dst:
            actions.append(("COPY", rel))
        elif (
            os.path.getsize(src_path) != os.path.getsize(dst[rel])
            or sha256_of(src_path) != sha256_of(dst[rel])
        ):
            actions.append(("UPDATE", rel))

    if delete:
        for rel in dst:
            if rel not in src:
                actions.append(("DELETE", rel))

    return sorted(actions, key=lambda a: (a[0], a[1]))


def apply_plan(src_root, dst_root, actions):
    """Execute the given actions, copying SRC -> DST."""
    for verb, rel in actions:
        src_path = os.path.join(src_root, rel)
        dst_path = os.path.join(dst_root, rel)
        if verb == "DELETE":
            os.remove(dst_path)
        else:  # COPY or UPDATE
            os.makedirs(os.path.dirname(dst_path), exist_ok=True)
            shutil.copy2(src_path, dst_path)
            # copy2 already copies mtime; utime makes the guarantee explicit.
            os.utime(dst_path, (os.stat(src_path).st_atime,
                                os.stat(src_path).st_mtime))


def main(argv=None):
    parser = argparse.ArgumentParser(description="One-way directory sync SRC -> DST")
    parser.add_argument("src", help="source directory")
    parser.add_argument("dst", help="destination directory")
    parser.add_argument("--delete", action="store_true",
                        help="delete files present only in DST")
    parser.add_argument("--dry-run", action="store_true",
                        help="print the plan and change nothing")
    args = parser.parse_args(argv)

    if not os.path.isdir(args.src):
        parser.error(f"source is not a directory: {args.src}")
    if not os.path.isdir(args.dst):
        parser.error(f"destination is not a directory: {args.dst}")

    actions = plan(args.src, args.dst, delete=args.delete)

    for verb, rel in actions:
        print(f"{verb} {rel}")

    if not args.dry_run:
        apply_plan(args.src, args.dst, actions)

    return 0


if __name__ == "__main__":
    sys.exit(main())
"})
